-- ============================================================================
-- Function: Auto-Heal Quarantined Tests
-- Unquarantine tests that have been stable
-- ============================================================================
CREATE OR REPLACE FUNCTION auto_heal_quarantined_tests(
    p_project_id UUID,
    p_heal_threshold REAL DEFAULT 0.1,
    p_min_consecutive_passes INTEGER DEFAULT 5
) RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER := 0;
    v_quarantine RECORD;
    v_score REAL;
    v_passes INTEGER;
BEGIN
    FOR v_quarantine IN
        SELECT * FROM test_quarantine
        WHERE project_id = p_project_id
    LOOP
        -- Calculate current flakiness
        v_score := calculate_flakiness_score(p_project_id, v_quarantine.test_id, 10);

        -- Count consecutive passes
        SELECT COUNT(*) INTO v_passes
        FROM (
            SELECT passed
            FROM test_results
            WHERE project_id = p_project_id
            AND test_id = v_quarantine.test_id
            ORDER BY created_at DESC
            LIMIT p_min_consecutive_passes
        ) sub
        WHERE passed = true;

        -- Unquarantine if healed
        IF v_score < p_heal_threshold AND v_passes >= p_min_consecutive_passes THEN
            DELETE FROM test_quarantine
            WHERE id = v_quarantine.id;

            v_count := v_count + 1;
        ELSE
            -- Update tracking
            UPDATE test_quarantine
            SET last_checked_at = NOW(),
                consecutive_passes = v_passes
            WHERE id = v_quarantine.id;
        END IF;
    END LOOP;

    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- Trigger: Clean up expired quarantines
-- ============================================================================
CREATE OR REPLACE FUNCTION cleanup_expired_quarantines()
RETURNS TRIGGER AS $$
BEGIN
    DELETE FROM test_quarantine
    WHERE expires_at IS NOT NULL AND expires_at < NOW();
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Run cleanup periodically (triggered by any test_results insert)
DROP TRIGGER IF EXISTS trigger_cleanup_quarantines ON test_results;
CREATE TRIGGER trigger_cleanup_quarantines
    AFTER INSERT ON test_results
    FOR EACH STATEMENT
    EXECUTE FUNCTION cleanup_expired_quarantines();

